import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Documents — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"documents-04-troubleshooting-and-faqs.md","filePath":"documents-04-troubleshooting-and-faqs.md"}'),r={name:"documents-04-troubleshooting-and-faqs.md"};function i(s,e,u,h,l,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="documents-—-troubleshooting-faqs" tabindex="-1">Documents — Troubleshooting &amp; FAQs <a class="header-anchor" href="#documents-—-troubleshooting-faqs" aria-label="Permalink to &quot;Documents — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common issues, edge cases, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="do-i-need-to-use-ai-to-generate-documents-or-can-i-write-them-manually" tabindex="-1">Do I need to use AI to generate Documents, or can I write them manually? <a class="header-anchor" href="#do-i-need-to-use-ai-to-generate-documents-or-can-i-write-them-manually" aria-label="Permalink to &quot;Do I need to use AI to generate Documents, or can I write them manually?&quot;">​</a></h3><p>Both options are available. You can generate a Document with AI and then edit it, or you can write from scratch using the manual option. Once a Document exists, there&#39;s no difference between the two — all Documents are fully editable regardless of how they were created.</p><h3 id="can-a-feature-have-multiple-documents-of-the-same-type" tabindex="-1">Can a Feature have multiple Documents of the same type? <a class="header-anchor" href="#can-a-feature-have-multiple-documents-of-the-same-type" aria-label="Permalink to &quot;Can a Feature have multiple Documents of the same type?&quot;">​</a></h3><p>No. Each Feature supports one Document per type — one PRD, one Opportunity Canvas, one Customer Email, and so on. If you need variations, edit and iterate within the single document rather than trying to create a second copy of the same type.</p><h3 id="what-happens-to-documents-if-i-delete-the-feature-they-belong-to" tabindex="-1">What happens to Documents if I delete the Feature they belong to? <a class="header-anchor" href="#what-happens-to-documents-if-i-delete-the-feature-they-belong-to" aria-label="Permalink to &quot;What happens to Documents if I delete the Feature they belong to?&quot;">​</a></h3><p>Documents cannot exist without a Feature. If you delete a Feature, all of its associated Documents are permanently deleted as well. There is no way to recover them.</p><h3 id="can-i-move-a-document-from-one-feature-to-another" tabindex="-1">Can I move a Document from one Feature to another? <a class="header-anchor" href="#can-i-move-a-document-from-one-feature-to-another" aria-label="Permalink to &quot;Can I move a Document from one Feature to another?&quot;">​</a></h3><p>No. Documents are attached to the Feature they were created for and cannot be reassigned. If you need a similar document for a different Feature, you&#39;ll need to generate or write a new one.</p><h3 id="who-can-see-documents" tabindex="-1">Who can see Documents? <a class="header-anchor" href="#who-can-see-documents" aria-label="Permalink to &quot;Who can see Documents?&quot;">​</a></h3><p>Documents are internal by default. They are only visible to members of your Lodestone workspace. They become shareable externally when exported as PDFs or PPTs, but they are never published or exposed automatically.</p><h3 id="can-i-export-documents-in-formats-other-than-pdf" tabindex="-1">Can I export Documents in formats other than PDF? <a class="header-anchor" href="#can-i-export-documents-in-formats-other-than-pdf" aria-label="Permalink to &quot;Can I export Documents in formats other than PDF?&quot;">​</a></h3><p>All Documents can be exported as PDF. The Opportunity Canvas also supports export as a single PowerPoint slide. No other export formats are currently available.</p><h3 id="will-regenerating-a-document-overwrite-my-edits" tabindex="-1">Will regenerating a Document overwrite my edits? <a class="header-anchor" href="#will-regenerating-a-document-overwrite-my-edits" aria-label="Permalink to &quot;Will regenerating a Document overwrite my edits?&quot;">​</a></h3><p>Yes, immediately and without a warning prompt. Regenerating replaces the entire existing Document with a new AI-generated version — there is no version history and no way to recover the previous content. If you&#39;ve made edits you want to keep, copy them somewhere safe before regenerating.</p><h3 id="can-i-share-a-document-directly-from-lodestone-without-exporting-it" tabindex="-1">Can I share a Document directly from Lodestone without exporting it? <a class="header-anchor" href="#can-i-share-a-document-directly-from-lodestone-without-exporting-it" aria-label="Permalink to &quot;Can I share a Document directly from Lodestone without exporting it?&quot;">​</a></h3><p>No. Export is the only way to share a Document externally. All Documents can be exported as PDF, and the Opportunity Canvas can also be exported as a PowerPoint slide. There is no shareable link or in-app sharing option.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="my-ai-generated-document-is-generic-and-doesn-t-reflect-our-product" tabindex="-1">My AI-generated Document is generic and doesn&#39;t reflect our product <a class="header-anchor" href="#my-ai-generated-document-is-generic-and-doesn-t-reflect-our-product" aria-label="Permalink to &quot;My AI-generated Document is generic and doesn&#39;t reflect our product&quot;">​</a></h3><p>This almost always comes down to one of two things:</p><ul><li><strong>Thin Feature Description</strong> — the AI has little to work with. Add more context: what problem does this solve, who is it for, what does success look like?</li><li><strong>Missing or vague Organization Description</strong> — go to Settings &gt; Organization and update it to accurately describe your company, industry, and customer base. This context is applied to every document generation.</li></ul><p>If both inputs are strong and output is still off, try a different document type — an Opportunity Canvas often produces more useful output at early stages than a PRD.</p><h3 id="the-generate-button-isn-t-producing-output" tabindex="-1">The Generate button isn&#39;t producing output <a class="header-anchor" href="#the-generate-button-isn-t-producing-output" aria-label="Permalink to &quot;The Generate button isn&#39;t producing output&quot;">​</a></h3><p>The most common cause is a missing Feature Description. Lodestone requires both a Feature Name and a Feature Description to generate a Document. If the Description field is empty, fill it in before trying again.</p><p>Also make sure you don&#39;t navigate away while generation is in progress — if you leave the page before generation completes, you&#39;ll return to a blank document.</p><h3 id="my-opportunity-canvas-isn-t-appearing-in-the-roadmap-ppt-export-appendix" tabindex="-1">My Opportunity Canvas isn&#39;t appearing in the Roadmap PPT export appendix <a class="header-anchor" href="#my-opportunity-canvas-isn-t-appearing-in-the-roadmap-ppt-export-appendix" aria-label="Permalink to &quot;My Opportunity Canvas isn&#39;t appearing in the Roadmap PPT export appendix&quot;">​</a></h3><p>Opportunity Canvases only appear in the Roadmap PPT export if they have been generated for Features that are included in that Roadmap. Check that:</p><ul><li>The Feature is included in the Roadmap you&#39;re exporting</li><li>An Opportunity Canvas has been generated for that Feature (not just other document types)</li></ul><p>If both are true and it&#39;s still not appearing, try regenerating the export.</p><h3 id="i-can-t-find-a-document-i-previously-created" tabindex="-1">I can&#39;t find a Document I previously created <a class="header-anchor" href="#i-can-t-find-a-document-i-previously-created" aria-label="Permalink to &quot;I can&#39;t find a Document I previously created&quot;">​</a></h3><p>Documents live on the Feature Detail page of the Feature they belong to. If you can&#39;t find a Document:</p><ul><li>Navigate to the Feature backlog and open the Feature by clicking its name</li><li>Scroll to the Documents section on the Feature Detail page</li></ul><p>If the Feature itself has been deleted, its Documents will have been permanently deleted along with it.</p><h3 id="the-exported-pdf-doesn-t-look-right" tabindex="-1">The exported PDF doesn&#39;t look right <a class="header-anchor" href="#the-exported-pdf-doesn-t-look-right" aria-label="Permalink to &quot;The exported PDF doesn&#39;t look right&quot;">​</a></h3><p>PDF exports paginate correctly and preserve formatting. If something looks off, try regenerating the export. If the issue persists, check whether the Document content contains any unusual formatting that may not translate cleanly to PDF.</p><hr><p><em>This is version 1 of the Documents documentation, based on the Lodestone knowledge base from early 2025, updated with confirmed platform behavior.</em></p>',41)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
